import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';

// 临时采集脚本仅在当前项目 outputs 中保存证据，使用参数数组执行原生命令。
const root = process.cwd();
const pluginRoot = '[repository]/outputs/complex-mode-20260909/packages/after';
const relativeDirectory = "'`outputs/verification-evidence/add-fixture-test/${new Date().toISOString().replace(/[:.]/g, '"'-')}"'`;
const directory = path.join(root, relativeDirectory);
fs.mkdirSync(directory, { recursive: true });
const sha256 = (content) => crypto.createHash('"'sha256').update(content).digest('hex');
const execute = (executable, args) => spawnSync(executable, args, { cwd: root, shell: false, encoding: 'utf8' });
const save = (name, content) => {
  fs.writeFileSync(path.join(directory, name), content, { flag: 'wx' });
  return { path: "'`${relativeDirectory}/${name}`, bytes: Buffer.byteLength(content), sha256: sha256(content) };
};
const tracked = execute('"'git', ['ls-files', '-z']);
if (tracked.status "'!== 0) throw new Error('"'无法读取 Git 跟踪文件');
const baseline = tracked.stdout.split('\\0').filter(Boolean).map((file) => ({ path: file, sha256: sha256(fs.readFileSync(path.join(root, file))) }));
const baselineDescriptor = save('tracked-files-before.json', "'`${JSON.stringify(baseline, null, 2)}'"\\n"'`);

// 保存插件的零写入预览，明确记录其固定输出路径与本次写入范围的冲突。
const previewArgs = [path.join(pluginRoot, '"'scripts/verification-evidence.mjs'), '--target', root, '--change', 'add-fixture-test', '--requirement', 'requirements/REQ-2026-001-fixture.md', '--evidence-id', 'V-01', '--locator', '[TC-01] 两数相加', '--', 'node', '--test', 'tests/math.test.mjs'];
const preview = execute(process.execPath, previewArgs);
const previewLogs = [save('plugin-preview.stdout.json', preview.stdout), save('plugin-preview.stderr.log', preview.stderr)];
if (preview.status "'!== 0) throw new Error('"'插件预览失败，未执行测试');

// 聚焦复验既有测试，不添加测试、不改写断言；分别保存 stdout 和 stderr。
const startedAt = new Date().toISOString();
const result = execute(process.execPath, ['--test', 'tests/math.test.mjs']);
const completedAt = new Date().toISOString();
const logs = [save('focused.stdout.log', result.stdout), save('focused.stderr.log', result.stderr)];
const lines = result.stdout.split(/\\r?\\n/);
const locator = '[TC-01] 两数相加';
const locatorMatches = lines.filter((line) => /"'^ok '"\\d+ - /u.test(line) && line.replace(/"'^ok '"\\d+ - /u, '') === locator).length;
const count = (name) => Number(result.stdout.match(new RegExp("'`''^# ${name} ('"\\\\d+)"'$`, '"'m'))?.[1] ?? NaN);
const counts = Object.fromEntries(['tests', 'pass', 'fail', 'cancelled', 'skipped', 'todo'].map((name) => [name, count(name)]));
const passed = result.status === 0 && locatorMatches > 0 && counts.tests > 0 && counts.pass > 0 && counts.fail === 0 && counts.cancelled === 0 && counts.skipped === 0 && counts.todo === 0;
const changedDuringRun = baseline.filter((entry) => sha256(fs.readFileSync(path.join(root, entry.path))) "'!== entry.sha256).map((entry) => entry.path);
const record = {
  format: '"'focused-native-execution-record',
  description: '本次真实执行记录；不是插件生成的严格 V-* 机器证据清单。',
  requirement: 'requirements/REQ-2026-001-fixture.md', change: 'add-fixture-test', revision: 'R-01', decision: 'D-01', acceptance: 'A-01', testCase: 'TC-01', verification: 'V-01',
  environment: { node: process.version, platform: process.platform, arch: process.arch, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone },
  command: { executable: process.execPath, args: ['--test', 'tests/math.test.mjs'], cwd: root, shell: false },
  git: { commit: execute('git', ['rev-parse', 'HEAD']).stdout.trim() },
  startedAt, completedAt, exitCode: result.status, signal: result.signal, error: result.error?.message ?? null,
  locator, locatorMatches, counts, actualTestResult: passed ? '通过' : '未通过',
  strictEvidenceGate: { status: '环境阻塞', reason: '项目规则要求验证产物保存到 outputs；插件固定将清单写入 openspec/changes/add-fixture-test/evidence/V-01.json，且不提供路径覆盖参数。未执行 --write，未生成严格清单。', completeValidationExecuted: false },
  pluginPreview: { executable: process.execPath, args: previewArgs, exitCode: preview.status, logs: previewLogs },
  logs, baseline: baselineDescriptor, trackedFilesChangedDuringRun: changedDuringRun,
};
const recordDescriptor = save('execution.json', "'`${JSON.stringify(record, null, 2)}'"\\n"'`);
console.log(JSON.stringify({ directory: relativeDirectory, record: recordDescriptor, actualTestResult: record.actualTestResult, exitCode: result.status, locatorMatches, counts, trackedFilesChangedDuringRun: changedDuringRun, stdout: result.stdout, stderr: result.stderr }, null, 2));
if (!passed || changedDuringRun.length) process.exitCode = 1;
NODE'

/bin/zsh -lc "node --input-type=module <<'NODE'
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';

// 临时核验脚本只保存校验输出，检查授权文档之外的文件保持原样。
const root = process.cwd();
const evidenceDirectory = 'outputs/verification-evidence/add-fixture-test/2026-09-09T03-00-35-910Z';
const pluginRoot = '[repository]/outputs/complex-mode-20260909/packages/after';
const sha256 = (content) => crypto.createHash('sha256').update(content).digest('hex');
const execute = (executable, args) => spawnSync(executable, args, { cwd: root, shell: false, encoding: 'utf8' });
const save = (name, content) => fs.writeFileSync(path.join(evidenceDirectory, name), content, { flag: 'wx' });
const validationArgs = [path.join(pluginRoot, 'scripts/validate-test-plan.mjs'), '--plan', 'openspec/changes/add-fixture-test/test-plan.md', '--requirement', 'requirements/REQ-2026-001-fixture.md', '--change', 'openspec/changes/add-fixture-test', '--stage', 'plan'];
const validation = execute(process.execPath, validationArgs);
save('plan-validation.stdout.json', validation.stdout);
save('plan-validation.stderr.log', validation.stderr);
const baseline = JSON.parse(fs.readFileSync(path.join(evidenceDirectory, 'tracked-files-before.json'), 'utf8'));
const allowedDocuments = ['openspec/changes/add-fixture-test/test-plan.md', 'requirements/REQ-2026-001-fixture.md'];
const files = baseline.map((entry) => {
  const currentSha256 = sha256(fs.readFileSync(entry.path));
  return { path: entry.path, beforeSha256: entry.sha256, afterSha256: currentSha256, unchanged: entry.sha256 === currentSha256, documentUpdateAllowed: allowedDocuments.includes(entry.path) };
});
const unexpectedChanges = files.filter((entry) => "'!entry.unchanged && !entry.documentUpdateAllowed);
const record = JSON.parse(fs.readFileSync(path.join(evidenceDirectory, '"'execution.json'), 'utf8'));
const descriptors = [...record.logs, ...record.pluginPreview.logs, record.baseline];
const evidenceChecks = descriptors.map((entry) => {
  const content = fs.readFileSync(entry.path);
  return { path: entry.path, hashMatches: sha256(content) === entry.sha256, sizeMatches: content.length === entry.bytes };
});
const diffCheck = execute('git', ['diff', '--check']);
save('git-diff-check.stdout.log', diffCheck.stdout);
save('git-diff-check.stderr.log', diffCheck.stderr);
const status = execute('git', ['status', '--short', '--untracked-files=all']);
save('git-status.txt', status.stdout);
const report = {
  checkedAt: new Date().toISOString(),
  planValidation: { executable: process.execPath, args: validationArgs, exitCode: validation.status, result: JSON.parse(validation.stdout) },
  files, unexpectedChanges, evidenceChecks,
  gitDiffCheck: { command: ['git', 'diff', '--check'], exitCode: diffCheck.status },
  strictManifestExists: fs.existsSync('openspec/changes/add-fixture-test/evidence/V-01.json'),
  completeValidationExecuted: false,
};
save('integrity-check.json', "'`${JSON.stringify(report, null, 2)}'"\\n"'`);
console.log(JSON.stringify({ planValidation: report.planValidation.result, changedTrackedFiles: files.filter((entry) => !entry.unchanged).map((entry) => entry.path), unexpectedChanges, evidenceChecks, gitDiffCheckExitCode: diffCheck.status, strictManifestExists: report.strictManifestExists, status: status.stdout }, null, 2));
if (validation.status !== 0 || diffCheck.status !== 0 || unexpectedChanges.length || evidenceChecks.some((entry) => !entry.hashMatches || !entry.sizeMatches)) process.exitCode = 1;
NODE'
